    @classmethod
    def _evaluate_order(
        cls,
        order: Mapping[str, Any],
        spec: Mapping[str, Any],
        *,
        window_start: datetime,
        window_end: datetime | None,
    ) -> tuple[dict[str, Any], list[datetime | None]]:
        reasons: list[str] = []
        created_at = cls._try_parse_datetime(order.get("createdAt"))
        order_id_epoch = cls._prefixed_epoch(order.get("id"), "TB")
        if created_at is None or not cls._in_window(created_at, window_start, window_end):
            reasons.append("createdAt is missing or outside the causal window")
        if created_at is None or order_id_epoch != cls._epoch_ms(created_at):
            reasons.append("order id epoch does not exactly equal createdAt milliseconds")
        for field in ("address", "payment"):
            if order.get(field) != spec[field]:
                reasons.append(f"{field} object mismatch")
        for field in ("note", "status"):
            if order.get(field) != spec[field]:
                reasons.append(f"{field} mismatch")
        if not cls._number_equal(order.get("total"), spec["total"]):
            reasons.append("total mismatch")

        items = order.get("items")
        expected_items = list(spec["items"])
        item_times: list[datetime | None] = []
        if not isinstance(items, list) or len(items) != len(expected_items):
            reasons.append(
                f"item cardinality mismatch: expected {len(expected_items)}, "
                f"observed {len(items) if isinstance(items, list) else 'non-list'}"
            )
            items = items if isinstance(items, list) else []
        seen_item_ids: set[str] = set()
        for index, expected in enumerate(expected_items):
            if index >= len(items) or not isinstance(items[index], Mapping):
                reasons.append(f"item {index + 1} is missing or invalid")
                item_times.append(None)
                continue
            item = items[index]
            product = item.get("product") if isinstance(item.get("product"), Mapping) else {}
            exact_fields = {
                "product.id": (product.get("id"), expected["product_id"]),
                "product.title": (product.get("title"), expected["title"]),
                "product.category": (product.get("category"), expected["category"]),
                "selectedSpec": (item.get("selectedSpec"), expected["selected_spec"]),
                "quantity": (item.get("quantity"), expected["quantity"]),
            }
            for label, (observed, wanted) in exact_fields.items():
                if observed != wanted:
                    reasons.append(f"item {index + 1} {label} mismatch")
            for label, key in (("unitPrice", "unit_price"), ("lineTotal", "line_total")):
                if not cls._number_equal(item.get(label), expected[key]):
                    reasons.append(f"item {index + 1} {label} mismatch")
            if not cls._number_equal(
                cls._multiply(item.get("unitPrice"), item.get("quantity")),
                item.get("lineTotal"),
            ):
                reasons.append(f"item {index + 1} lineTotal is not unitPrice * quantity")
            item_id = str(item.get("id") or "")
            if item_id in seen_item_ids:
                reasons.append(f"item {index + 1} id is duplicated")
            seen_item_ids.add(item_id)
            item_epoch = cls._prefixed_epoch(item_id, "cart-")
            item_time = cls._datetime_from_epoch_ms(item_epoch)
            item_times.append(item_time)
            if item_time is None or not cls._in_window(item_time, window_start, window_end):
                reasons.append(f"item {index + 1} cart id epoch is missing or outside window")
            if created_at is not None and (item_time is None or item_time >= created_at):
                reasons.append(f"item {index + 1} was not durably added before order creation")

        observed = {
            "id": order.get("id"),
            "createdAt": order.get("createdAt"),
            "address": order.get("address"),
            "payment": order.get("payment"),
            "note": order.get("note"),
            "status": order.get("status"),
            "total": order.get("total"),
            "items": [
                {
                    "id": item.get("id"),
                    "product_id": (
                        item.get("product", {}).get("id")
                        if isinstance(item, Mapping) and isinstance(item.get("product"), Mapping)
                        else None
                    ),
                    "title": (
                        item.get("product", {}).get("title")
                        if isinstance(item, Mapping) and isinstance(item.get("product"), Mapping)
                        else None
                    ),
                    "category": (
                        item.get("product", {}).get("category")
                        if isinstance(item, Mapping) and isinstance(item.get("product"), Mapping)
                        else None
                    ),
                    "selectedSpec": item.get("selectedSpec") if isinstance(item, Mapping) else None,
                    "quantity": item.get("quantity") if isinstance(item, Mapping) else None,
                    "unitPrice": item.get("unitPrice") if isinstance(item, Mapping) else None,
                    "lineTotal": item.get("lineTotal") if isinstance(item, Mapping) else None,
                }
                for item in items
            ],
        }
        return (
            cls._check(
                str(spec["name"]),
                spec["steps"],
                ["final_object", "content", "relationship"],
                not reasons,
                spec,
                observed,
                "; ".join(reasons),
            ),
            item_times,
        )

    @classmethod
    def _evaluate_review(
        cls,
        order: Mapping[str, Any] | None,
        spec: Mapping[str, Any],
        *,
        window_start: datetime,
        window_end: datetime | None,
    ) -> tuple[dict[str, Any], datetime | None]:
        reasons: list[str] = []
        matching_items: list[Mapping[str, Any]] = []
        if isinstance(order, Mapping):
            items = order.get("items") if isinstance(order.get("items"), list) else []
            for item in items:
                product = item.get("product") if isinstance(item, Mapping) else None
                if isinstance(product, Mapping) and product.get("id") == spec["product_id"]:
                    matching_items.append(item)
        if len(matching_items) != 1:
            reasons.append(f"expected exactly one target item, observed {len(matching_items)}")
        review = matching_items[0].get("review") if matching_items else None
        reviewed_at = cls._try_parse_datetime(
            review.get("reviewedAt") if isinstance(review, Mapping) else None
        )
        expected_review = {"rating": spec["rating"], "review": spec["review"]}
        if not isinstance(review, Mapping):
            reasons.append("review object is missing")
        else:
            if review.get("rating") != spec["rating"]:
                reasons.append("rating mismatch")
            if review.get("review") != spec["review"]:
                reasons.append("review text mismatch")
            if reviewed_at is None or not cls._in_window(reviewed_at, window_start, window_end):
                reasons.append("reviewedAt is missing or outside the causal window")

        if isinstance(order, Mapping):
            allowed_review_products = {"p1005", "p1001"}
            for item in order.get("items", []):
                if not isinstance(item, Mapping):
                    continue
                product = item.get("product") if isinstance(item.get("product"), Mapping) else {}
                if product.get("id") not in allowed_review_products and "review" in item:
                    reasons.append(f"unexpected review on product {product.get('id')!r}")

        return (
            cls._check(
                str(spec["name"]),
                spec["steps"],
                ["final_object", "content", "relationship"],
                not reasons,
                expected_review,
                review,
                "; ".join(reasons),
            ),
            reviewed_at,
        )

    @staticmethod
    def _check(
        name: str,
        steps: Sequence[int],
        dimensions: Sequence[str],
        passed: bool,
        expected: Any,
        observed: Any,
        failure_reason: str = "",
    ) -> dict[str, Any]:
        return {
            "name": name,
            "steps": list(steps),
            "dimensions": list(dimensions),
            "pass": bool(passed),
            "expected": expected,
            "observed": observed,
            "failure_reason": "" if passed else (failure_reason or f"{name} mismatch"),
        }

    @classmethod
    def _step_coverage(cls, checks: Sequence[Mapping[str, Any]]) -> list[dict[str, Any]]:
        by_name = {str(check.get("name")): check for check in checks}
        chain_for_step: dict[int, str] = {}
        for chain, steps in STEP_GROUPS.items():
            for step in steps:
                chain_for_step[step] = chain
        direct_check_names: dict[int, list[str]] = {step: [] for step in range(1, 74)}
        for check in checks:
            for step in check.get("steps", []):
                if isinstance(step, int) and step in direct_check_names:
                    direct_check_names[step].append(str(check.get("name")))

        chain_check = {
            "authentication": "authentication_exact",
            "home_order": "home_order_exact",
            "coffee_review": "coffee_review_exact",
            "headphones_review": "headphones_review_exact",
            "office_order": "office_order_exact",
        }
        coverage: list[dict[str, Any]] = []
        for step in range(1, 74):
            chain = chain_for_step[step]
            checkpoint_names = list(direct_check_names[step])
            primary = chain_check[chain]
            if primary not in checkpoint_names:
                checkpoint_names.append(primary)
            relevant = [by_name[name] for name in checkpoint_names if name in by_name]
            passed = bool(relevant) and all(bool(item.get("pass")) for item in relevant)
            is_data_step = step in DATA_STEPS
            coverage.append(
                {
                    "step": step,
                    "covered": True,
                    "pass": passed,
                    "data_producing": is_data_step,
                    "checkpoint_names": checkpoint_names,
                    "dimensions": {
                        "final_object": primary,
                        "content": "exact persisted fields or compound submission" if is_data_step else "not independently persisted",
                        "source_or_process": "exact localStorage v3 state and strict causal window",
                        "final_ui": "not required; no final UI claim is inferred",
                    },
                    "mapping_basis": (
                        "direct or compound persisted business evidence"
                        if is_data_step
                        else "required navigation for the named durable chain; no invented event asserted"
                    ),
                }
            )
        return coverage

    @classmethod
    def _state_failure(
        cls,
        *,
        checks: list[dict[str, Any]],
        reason: str,
        window_start: datetime,
        window_end: datetime | None,
        window_source: str,
        app_binding: Mapping[str, Any],
        database_evidence: Mapping[str, Any] | None,
    ) -> EvalResult:
        checks.append(
            cls._check(
                "account_state_present",
                [],
                ["final_object", "source_or_process"],
                False,
                ACCOUNT_PHONE,
                None,
                reason,
            )
        )
        step_coverage = cls._step_coverage(checks)
        return EvalResult(
            status=EvalStatus.FAIL,
            message="OpenShop1 account state is unavailable",
            metadata={
                "read_only": True,
                "ruleset_sha256": RULESET_SHA256,
                "instruction_sha256": INSTRUCTION_SHA256,
                "ruleset_spec": RULESET_SPEC,
                "checks": checks,
                "failures": [check for check in checks if not check["pass"]],
                "step_coverage": step_coverage,
                "coverage_summary": {
                    "instruction_steps": 73,
                    "covered_steps": 73,
                    "passing_steps": sum(1 for item in step_coverage if item["pass"]),
                    "data_steps": list(DATA_STEPS),
                    "uncovered_data_steps": [],
                },
                "causal_window": {
                    "source": window_source,
                    "start": window_start.isoformat(),
                    "end": window_end.isoformat() if window_end else None,
                },
                "observed": {
                    "applications": list(app_binding.get("applications") or []),
                    "database": dict(database_evidence or {}),
                },
                "safety": cls._safety_attestation(),
            },
        )

    @classmethod
    def _resolve_causal_window(
        cls,
        *,
        context: Mapping[str, Any],
        params: Mapping[str, Any],
    ) -> tuple[datetime, datetime | None, str]:
        run_dir_raw = context.get("run_dir")
        if run_dir_raw:
            args_path = Path(str(run_dir_raw)).expanduser().resolve() / "args.json"
            payload = json.loads(args_path.read_text(encoding="utf-8"))
            created_at = cls._parse_datetime(payload.get("created_at"), "args.json.created_at")
            return created_at, None, "automatic_run_args_created_at"
        start = cls._parse_datetime(
            params.get("manual_window_start") or MANUAL_WINDOW_START,
            "manual_window_start",
        )
        end = cls._parse_datetime(
            params.get("manual_window_end") or MANUAL_WINDOW_END,
            "manual_window_end",
        )
        if end <= start:
            raise ValueError("manual_window_end must be later than manual_window_start")
        return start, end, "manual_recording_window"

    @classmethod
    def _resolve_live_binding(
        cls,
        *,
        udid: str,
        bundle_id: str,
    ) -> tuple[Path, dict[str, Any]]:
        data_container = cls._simctl_container(udid, bundle_id, "data")
        app_container = cls._simctl_container(udid, bundle_id, "app")
        origin_root = data_container / "Library" / "WebKit" / bundle_id / "WebsiteData" / "Default"
        origin_files = sorted(origin_root.glob("*/*/origin"))
        active = [path for path in origin_files if cls._origin_is_exact(path.read_bytes())]
        if len(active) != 1:
            raise RuntimeError(
                f"expected exactly one {EXPECTED_ORIGIN} WebKit origin, observed {len(active)}"
            )
        db_path = active[0].parent / "LocalStorage" / "localstorage.sqlite3"
        if not db_path.is_file():
            raise FileNotFoundError(f"active-origin localStorage database is missing: {db_path}")

        public_dir = app_container / "public"
        app_js = public_dir / "app.js"
        seed_data = public_dir / "seed-data.js"
        app_js_sha256 = cls._file_sha256(app_js)
        seed_data_sha256 = cls._file_sha256(seed_data)
        if app_js_sha256 != EXPECTED_APP_JS_SHA256:
            raise RuntimeError(
                f"app.js SHA-256 mismatch: expected {EXPECTED_APP_JS_SHA256}, got {app_js_sha256}"
            )
        if seed_data_sha256 != EXPECTED_SEED_DATA_SHA256:
            raise RuntimeError(
                "seed-data.js SHA-256 mismatch: "
                f"expected {EXPECTED_SEED_DATA_SHA256}, got {seed_data_sha256}"
            )
        seed_account = cls._read_seed_account(seed_data)
        expected_account = {
            "id": ACCOUNT_ID,
            "name": ACCOUNT_NAME,
            "phone": ACCOUNT_PHONE,
            "passwordHash": EXPECTED_PASSWORD_HASH,
        }
        observed_account = {key: seed_account.get(key) for key in expected_account}
        if observed_account != expected_account:
            raise RuntimeError(
                f"seed account mismatch: expected {expected_account!r}, got {observed_account!r}"
            )

        applications = [
            {
                "bundle_id": bundle_id,
                "origin": EXPECTED_ORIGIN,
                "local_state_key": LOCAL_STATE_KEY,
                "app_container": str(app_container),
                "data_container": str(data_container),
                "app_js_sha256": app_js_sha256,
                "seed_data_sha256": seed_data_sha256,
            }
        ]
        return db_path, {
            "pass": True,
            "bundle_id": bundle_id,
            "origin": EXPECTED_ORIGIN,
            "local_state_key": LOCAL_STATE_KEY,
            "active_origin_count": 1,
            "origin_file_count": len(origin_files),
            "database_path": str(db_path),
            "seed_account": observed_account,
            "applications": applications,
        }

    @staticmethod
    def _simctl_container(udid: str, bundle_id: str, kind: str) -> Path:
        proc = subprocess.run(
            ["xcrun", "simctl", "get_app_container", udid, bundle_id, kind],
            capture_output=True,
            text=True,
            timeout=30,
        )
        if proc.returncode != 0:
            raise RuntimeError(
                f"simctl get_app_container {kind} failed: {proc.stderr.strip()}"
            )
        from platforms.ios.runtime_env.simulator_manager import remap_simulator_container_path
        path = remap_simulator_container_path(proc.stdout.strip(), udid)
        if not path.exists():
            raise FileNotFoundError(f"simctl {kind} container does not exist: {path}")
        return path

    @staticmethod
    def _origin_is_exact(payload: bytes) -> bool:
        def component(value: bytes) -> bytes:
            return struct.pack("<I", len(value)) + b"\x01" + value

        record = component(b"capacitor") + component(b"localhost") + b"\x00"
        return payload == record + record

    @classmethod
    def _read_seed_account(cls, path: Path) -> dict[str, Any]:
        raw = path.read_text(encoding="utf-8")
        start = raw.find("{")
        end = raw.rfind("}")
        if start < 0 or end < start:
            raise ValueError(f"Could not parse OpenShop seed payload from {path}")
        payload = json.loads(raw[start : end + 1])
        accounts = payload.get("accounts") if isinstance(payload, Mapping) else None
        if not isinstance(accounts, list):
            accounts = [payload.get("benchmarkAccount")] if isinstance(payload, Mapping) else []
        matches = [
            account
            for account in accounts
            if isinstance(account, Mapping) and str(account.get("phone") or "") == ACCOUNT_PHONE
        ]
        if len(matches) != 1:
            raise RuntimeError(
                f"expected exactly one seed account for {ACCOUNT_PHONE}, observed {len(matches)}"
            )
        return dict(matches[0])

    @classmethod
    def _read_state_snapshot(
        cls,
        *,
        db_path: Path,
        local_state_key: str,
    ) -> tuple[dict[str, Any], dict[str, Any]]:
        if not db_path.is_file():
            raise FileNotFoundError(f"localStorage database not found: {db_path}")
        with tempfile.TemporaryDirectory(prefix="openshop1-verifier-") as temporary:
            snapshot = Path(temporary) / "localstorage.sqlite3"
            shutil.copy2(db_path, snapshot)
            copied_sidecars: list[str] = []
            for suffix in ("-wal", "-shm"):
                source = Path(f"{db_path}{suffix}")
                if source.is_file():
                    shutil.copy2(source, Path(f"{snapshot}{suffix}"))
                    copied_sidecars.append(suffix)
            conn = sqlite3.connect(f"file:{snapshot}?mode=ro", uri=True)
            try:
                quick_check = conn.execute("PRAGMA quick_check").fetchall()
                if quick_check != [("ok",)]:
                    raise RuntimeError(f"SQLite quick_check failed: {quick_check!r}")
                rows = conn.execute(
                    "SELECT value FROM ItemTable WHERE key = ?",
                    (local_state_key,),
                ).fetchall()
            finally:
                conn.close()
        if len(rows) != 1:
            raise RuntimeError(
                f"expected exactly one localStorage row for {local_state_key!r}, observed {len(rows)}"
            )
        raw = rows[0][0]
        if isinstance(raw, memoryview):
            raw = bytes(raw)
        if isinstance(raw, bytes):
            text = raw.decode("utf-16-le").rstrip("\x00")
        elif isinstance(raw, str):
            text = raw.rstrip("\x00")
        else:
            raise TypeError(f"unsupported localStorage value type: {type(raw)!r}")
        state = json.loads(text)
        if not isinstance(state, dict):
            raise TypeError("OpenShop local state must decode to an object")
        return state, {
            "quick_check": "ok",
            "snapshot_read": True,
            "sqlite_mode": "ro",
            "copied_sidecars": copied_sidecars,
            "local_state_key": local_state_key,
            "source_database_sha256": cls._file_sha256(db_path),
        }

    @classmethod
    def _error_result(cls, message: str) -> EvalResult:
        return EvalResult(
            status=EvalStatus.ERROR,
            message=message,
            metadata={
                "read_only": True,
                "ruleset_sha256": RULESET_SHA256,
                "instruction_sha256": INSTRUCTION_SHA256,
                "ruleset_spec": RULESET_SPEC,
                "checks": [],
                "failures": [],
                "step_coverage": [],
                "coverage_summary": {
                    "instruction_steps": 73,
                    "covered_steps": 0,
                    "passing_steps": 0,
                    "data_steps": list(DATA_STEPS),
                    "uncovered_data_steps": list(DATA_STEPS),
                },
                "observed": {"applications": []},
                "safety": cls._safety_attestation(),
            },
        )

    @staticmethod
    def _safety_attestation() -> dict[str, bool]:
        return {
            "read_only": True,
            "sqlite_snapshot_to_host_temp": True,
            "simulator_reset": False,
            "simulator_restore": False,
            "initializer": False,
            "gui_action": False,
            "appium": False,
            "app_launched": False,
            "simulator_boot": False,
            "simulator_shutdown": False,
            "app_or_simulator_data_write": False,
        }

    @staticmethod
    def _parse_datetime(value: Any, label: str) -> datetime:
        parsed = OpenShopCoffeeBabyDualCheckout958608Evaluator._try_parse_datetime(value)
        if parsed is None:
            raise ValueError(f"{label} must be a timezone-aware ISO-8601 timestamp")
        return parsed

    @staticmethod
    def _try_parse_datetime(value: Any) -> datetime | None:
        text = str(value or "").strip()
        if not text:
            return None
        if text.endswith("Z"):
            text = f"{text[:-1]}+00:00"
        try:
            parsed = datetime.fromisoformat(text)
        except ValueError:
            return None
        if parsed.tzinfo is None:
            return None
        return parsed.astimezone(timezone.utc)

    @staticmethod
    def _in_window(value: datetime, start: datetime, end: datetime | None) -> bool:
        return value >= start and (end is None or value <= end)

    @staticmethod
    def _epoch_ms(value: datetime) -> int:
        return int(value.timestamp() * 1000)

    @staticmethod
    def _datetime_from_epoch_ms(value: int | None) -> datetime | None:
        if value is None:
            return None
        try:
            return datetime.fromtimestamp(value / 1000, tz=timezone.utc)
        except (OverflowError, OSError, ValueError):
            return None

    @staticmethod
    def _prefixed_epoch(value: Any, prefix: str) -> int | None:
        text = str(value or "")
        if not text.startswith(prefix):
            return None
        digits = text[len(prefix) :]
        if not digits.isdigit():
            return None
        return int(digits)

    @staticmethod
    def _number_equal(left: Any, right: Any) -> bool:
        try:
            return Decimal(str(left)) == Decimal(str(right))
        except (InvalidOperation, ValueError):
            return False

    @staticmethod
    def _multiply(left: Any, right: Any) -> Decimal | None:
        try:
            return Decimal(str(left)) * Decimal(str(right))
        except (InvalidOperation, ValueError):
            return None

    @staticmethod
    def _file_sha256(path: Path) -> str:
        if not path.is_file():
            raise FileNotFoundError(path)
        digest = hashlib.sha256()
        with path.open("rb") as handle:
            for chunk in iter(lambda: handle.read(1024 * 1024), b""):
                digest.update(chunk)
        return digest.hexdigest()


